function List-Tree([string]$sha, [string]$prefix='') {
  $raw = Read-Obj $sha
  if ($null -eq $raw) { return }
  $body = $raw.Substring($raw.IndexOf([char]0) + 1)
  $i = 0
  while ($i -lt $body.Length) {
    $sp = $body.IndexOf([char]0x20, $i)
    $mode = $body.Substring($i, $sp - $i)
    $i = $sp + 1
    $nul = $body.IndexOf([char]0, $i)
    $name = $body.Substring($i, $nul - $i)
    $i = $nul + 1
    $shaHex = -join ($body.Substring($i, 20).ToCharArray() | ForEach-Object { '{0:x2}' -f [int][char]$_ })
    $i += 20
    Write-Output ($prefix + $name + ' [' + $mode + '] ' + $shaHex)
  }
}
